                 //         },
                 //         "state": "open",
                 //         "voided": false,
                 //         "resolvedOutcomeId": "-1",
                 //         "topics": [ "Politics" ],
                 //         "resolutionSource": "https://www.whitehouse.gov/",
                 //         "resolutionTitle": "White House",
                 //         "token": {
                 //             "name": "Bridged USDC (Stargate)",
                 //             "address":
                 //             "0x84A71ccD554Cc1b02749b35d22F684CC8ec987e1",
                 //             "symbol": "USDC.e",
